export class AuditService {
  async log(input: {
    userId?: string;
    action: AuditAction;
    entity: string;
    entityId?: string;
    details?: Prisma.InputJsonValue;
    ipAddress?: string;
  }) {
    return prisma.auditLog.create({ data: input });
