}

a {
  color: inherit;
  text-decoration: none;
}

h1, h2, h3, .font-display {
  font-family: var(--font-display);
  letter-spacing: -0.02em;
}

.container-page {
  width: min(1180px, calc(100% - 2rem));
  margin-inline: auto;
}

.glass-panel {
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid rgba(213, 227, 219, 0.9);
