.badge-checked_in { background: #eff8ff; color: #175cd3; }
.badge-completed { background: #f0fdf4; color: #166534; }
.badge-cancelled, .badge-rejected, .badge-no_show { background: #fef3f2; color: #b42318; }
.badge-paid { background: #ecfdf3; color: #027a48; }

.stat-card {
  padding: 1.25rem;
  border-radius: 16px;
  background: white;
  border: 1px solid var(--line);
  box-shadow: 0 8px 24px rgba(15, 36, 28, 0.04);
}

.table-wrap {
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: white;
}

table.data {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.92rem;
}

table.data th,
table.data td {
  padding: 0.9rem 1rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}

table.data th {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-muted);
  background: #f8fbf9;
}

table.data tr:last-child td {
  border-bottom: none;
}

.sidebar-link {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.7rem 0.9rem;
  border-radius: 12px;
  color: var(--ink-muted);
  font-weight: 600;
  transition: background 0.15s ease, color 0.15s ease;
}

.sidebar-link:hover,
.sidebar-link.active {
  background: var(--brand-soft);
  color: var(--brand-deep);
}

.fade-up {
  animation: fadeUp 0.55s ease both;
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes floaty {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.floaty {
  animation: floaty 5s ease-in-out infinite;
}

@media (max-width: 900px) {
  .hide-mobile { display: none !important; }
}

