import { AuthProvider } from '@/contexts/auth-context';
import './globals.css';

const display = Fraunces({
  subsets: ['latin'],
  variable: '--font-display',
  weight: ['500', '600', '700'],
});

const body = Manrope({
  subsets: ['latin'],
  variable: '--font-body',
  weight: ['400', '500', '600', '700', '800'],
});

export const metadata: Metadata = {
  title: 'DoctorCare — Appointment Management',
  description: 'Book doctors, manage appointments, prescriptions and billing in one calm clinic workspace.',
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en">
      <body className={`${display.variable} ${body.variable} antialiased`}>
        <AuthProvider>
          {children}
          <Toaster position="top-right" toastOptions={{ duration: 3000 }} />
        </AuthProvider>
      </body>
    </html>
  );
}

'use client';

import Link from 'next/link';
import { FormEvent, useState } from 'react';
import { Stethoscope } from 'lucide-react';
import { useAuth, getErrorMessage } from '@/contexts/auth-context';
import { APP_NAME } from '@/config';
import toast from 'react-hot-toast';

export default function LoginPage() {
  const { login } = useAuth();
  const [email, setEmail] = useState('patient@doctorcare.local');
  const [password, setPassword] = useState('Password@123');
  const [loading, setLoading] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setLoading(true);
    try {
      await login(email, password);
    } catch (err) {
      toast.error(getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen grid lg:grid-cols-2">
      <div
        className="hidden lg:block relative"
        style={{
          backgroundImage:
            'linear-gradient(160deg, rgba(8,76,59,0.9), rgba(13,110,86,0.55)), url(https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?auto=format&fit=crop&w=1400&q=80)',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
        }}
      >
        <div className="absolute inset-0 p-12 flex flex-col justify-end text-white">
          <h1 className="font-display text-5xl max-w-md leading-tight">{APP_NAME}</h1>
          <p className="mt-4 text-white/80 max-w-sm">Sign in to manage visits, prescriptions, and clinic operations.</p>
        </div>
      </div>

      <div className="grid place-items-center p-6">
        <form onSubmit={onSubmit} className="w-full max-w-md glass-panel p-8 fade-up">
          <Link href="/" className="flex items-center gap-2 mb-6">
            <span className="h-9 w-9 rounded-xl bg-[var(--brand)] text-white grid place-items-center">
              <Stethoscope size={16} />
            </span>
            <span className="font-display text-xl">{APP_NAME}</span>
          </Link>
          <h2 className="font-display text-3xl">Welcome back</h2>
          <p className="text-sm text-[var(--ink-muted)] mt-1 mb-6">Use a demo account or your credentials.</p>

          <label className="label">Email</label>
          <input className="input mb-4" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />

          <label className="label">Password</label>
          <input className="input mb-2" type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />

          <div className="flex justify-between text-sm mb-6">
            <Link href="/forgot-password" className="text-[var(--brand)] font-semibold">Forgot password?</Link>
          </div>

          <button className="btn btn-primary w-full" disabled={loading}>
            {loading ? 'Signing in…' : 'Sign in'}
          </button>

          <p className="text-sm text-center mt-5 text-[var(--ink-muted)]">
            New patient? <Link href="/register" className="text-[var(--brand)] font-semibold">Create account</Link>
          </p>

          <div className="mt-6 rounded-xl bg-[var(--brand-soft)] p-3 text-xs text-[var(--brand-deep)] space-y-1">
            <div><strong>Admin:</strong> admin@doctorcare.local</div>
            <div><strong>Doctor:</strong> doctor@doctorcare.local</div>
            <div><strong>Staff:</strong> staff@doctorcare.local</div>
            <div><strong>Patient:</strong> patient@doctorcare.local</div>
            <div>Password: <strong>Password@123</strong></div>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { FormEvent, useState } from 'react';
import { useAuth, getErrorMessage } from '@/contexts/auth-context';
import { APP_NAME } from '@/config';
import toast from 'react-hot-toast';

export default function RegisterPage() {
  const { register } = useAuth();
  const [form, setForm] = useState({ name: '', email: '', phone: '', password: '' });
  const [loading, setLoading] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setLoading(true);
    try {
      await register(form);
    } catch (err) {
      toast.error(getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen grid place-items-center p-6">
      <form onSubmit={onSubmit} className="w-full max-w-lg glass-panel p-8 fade-up">
        <h1 className="font-display text-3xl text-[var(--brand-deep)]">Join {APP_NAME}</h1>
        <p className="text-sm text-[var(--ink-muted)] mt-1 mb-6">Create a patient account to book appointments online.</p>

        <label className="label">Full name</label>
        <input className="input mb-4" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />

        <label className="label">Email</label>
        <input className="input mb-4" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required />

        <label className="label">Phone</label>
        <input className="input mb-4" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />

        <label className="label">Password</label>
        <input className="input mb-6" type="password" minLength={8} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required />

        <button className="btn btn-primary w-full" disabled={loading}>
          {loading ? 'Creating…' : 'Create account'}
        </button>

        <p className="text-sm text-center mt-5 text-[var(--ink-muted)]">
          Already registered? <Link href="/login" className="text-[var(--brand)] font-semibold">Sign in</Link>
        </p>
      </form>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { FormEvent, useState } from 'react';
import { authApi } from '@/services/api';
import { getErrorMessage } from '@/lib/api';
import toast from 'react-hot-toast';

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [done, setDone] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    try {
      await authApi.forgotPassword(email);
      setDone(true);
      toast.success('If that email exists, instructions were sent.');
    } catch (err) {
      toast.error(getErrorMessage(err));
    }
  }

  return (
    <div className="min-h-screen grid place-items-center p-6">
      <form onSubmit={onSubmit} className="w-full max-w-md glass-panel p-8">
        <h1 className="font-display text-3xl">Reset password</h1>
        <p className="text-sm text-[var(--ink-muted)] mt-2 mb-6">
          Enter your email and we will send reset instructions when email is configured.
        </p>
        {done ? (
          <p className="text-[var(--success)] font-semibold">Check your inbox for next steps.</p>
        ) : (
          <>
            <label className="label">Email</label>
            <input className="input mb-6" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
            <button className="btn btn-primary w-full">Send reset link</button>
          </>
